diff --git a/design-system/emails/new-request-notification.html b/design-system/emails/new-request-notification.html
new file mode 100644
index 0000000..43dac05
--- /dev/null
+++ b/design-system/emails/new-request-notification.html
@@ -0,0 +1,489 @@
+<!-- @dsCard group="Onboarding Requests" viewport="920x1180" name="New request notification email" subtitle="Memba.Onboarding.NewRequestEmail staff notification with direct /admin/requests/:request_id link" -->
+<!-- @startingPoint section="Onboarding Requests" subtitle="Staff email sent when a verified requester asks Memba to create a new group space" viewport="920x1180" -->
+<!doctype html>
+<html lang="en" data-theme="light">
+<head>
+  <meta charset="utf-8">
+  <title>New request notification email · Memba</title>
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap">
+
+  <!-- daisyUI component CSS, prebuilt — renders the app's daisyUI components with no build step. -->
+  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/daisyui@5">
+
+  <style>
+    /* Memba raw tokens (mirror of web/assets/css/app.css @theme). */
+    :root {
+      --color-sage-50:#eef1e6;
+      --color-sage-100:#dde3cf;
+      --color-sage-200:#bccaa6;
+      --color-sage-300:#98ab80;
+      --color-sage-400:#6f8760;
+      --color-sage-500:#5a7050;
+      --color-sage-600:#475a40;
+      --color-sage-700:#36462f;
+      --color-sage-800:#232e1e;
+
+      --color-cream:#f6f5ea;
+      --color-paper:#fffef9;
+      --color-apricot:#d2925a;
+      --color-apricot-soft:#f6e8d6;
+      --color-apricot-deep:#925f2e;
+
+      --color-ink:#25291d;
+      --color-ink-2:#555a47;
+      --color-ink-3:#878b76;
+
+      --color-line:#e8e6d4;
+      --color-line-strong:#d9d6bf;
+      --color-success:#5f7a4f;
+      --color-warning:#a8772e;
+      --color-error:#a8503a;
+      --color-info:#4f6b78;
+      --color-success-soft:#e9eedd;
+      --color-warning-soft:#f3ecd8;
+      --color-error-soft:#f1ddd3;
+      --color-info-soft:#e3e9ec;
+
+      --font-sans:"Figtree",ui-sans-serif,system-ui,sans-serif;
+      --font-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
+    }
+
+    /* daisyUI "light" theme — copied from web/assets/css/app.css. */
+    :root {
+      color-scheme:light;
+      --color-base-100:#fffef9;
+      --color-base-200:#f6f5ea;
+      --color-base-300:#e8e6d4;
+      --color-base-content:#25291d;
+      --color-primary:#5a7050;
+      --color-primary-content:#f6f5ea;
+      --color-secondary:#555a47;
+      --color-secondary-content:#f6f5ea;
+      --color-accent:#d2925a;
+      --color-accent-content:#25291d;
+      --color-neutral:#25291d;
+      --color-neutral-content:#f6f5ea;
+      --color-info:#4f6b78;
+      --color-info-content:#f6f5ea;
+      --color-success:#5f7a4f;
+      --color-success-content:#f6f5ea;
+      --color-warning:#a8772e;
+      --color-warning-content:#f6f5ea;
+      --color-error:#a8503a;
+      --color-error-content:#f6f5ea;
+      --radius-selector:0.375rem;
+      --radius-field:0.375rem;
+      --radius-box:0.75rem;
+      --size-selector:0.25rem;
+      --size-field:0.25rem;
+      --border:1px;
+      --depth:0;
+      --noise:0;
+    }
+
+    * { box-sizing:border-box; }
+    html, body { margin:0; }
+    body {
+      min-height:100vh;
+      background:var(--color-base-200);
+      color:var(--color-base-content);
+      font-family:var(--font-sans);
+      -webkit-font-smoothing:antialiased;
+      text-rendering:optimizeLegibility;
+    }
+    a { color:inherit; text-decoration:none; }
+    h1, h2, h3, p { margin:0; }
+    code, pre { font-family:var(--font-mono); }
+
+    .preview-shell {
+      display:grid;
+      gap:28px;
+      padding:28px;
+    }
+    .preview-title {
+      align-items:flex-end;
+      display:flex;
+      gap:18px;
+      justify-content:space-between;
+      margin:0 auto;
+      max-width:860px;
+      width:100%;
+    }
+    .preview-title__eyebrow {
+      color:var(--color-ink-3);
+      font-size:12px;
+      font-weight:700;
+      letter-spacing:0.18em;
+      text-transform:uppercase;
+    }
+    .preview-title h1 {
+      color:var(--color-ink);
+      font-size:34px;
+      font-weight:700;
+      letter-spacing:-0.035em;
+      line-height:1.05;
+      margin-top:5px;
+    }
+    .preview-title p {
+      color:var(--color-ink-2);
+      font-size:14px;
+      line-height:1.45;
+      margin-top:8px;
+      max-width:62ch;
+    }
+    .variant-label {
+      border:1px solid var(--color-line-strong);
+      border-radius:999px;
+      color:var(--color-ink-2);
+      font-family:var(--font-mono);
+      font-size:11px;
+      padding:7px 10px;
+      white-space:nowrap;
+    }
+
+    .mail-preview {
+      background:var(--color-paper);
+      border:1px solid var(--color-line-strong);
+      border-radius:24px;
+      box-shadow:0 18px 46px rgba(37,41,29,0.08);
+      margin:0 auto;
+      max-width:860px;
+      overflow:hidden;
+      width:100%;
+    }
+    .mail-preview__bar {
+      align-items:center;
+      background:var(--color-sage-800);
+      color:var(--color-cream);
+      display:flex;
+      gap:14px;
+      justify-content:space-between;
+      padding:12px 16px;
+    }
+    .mail-preview__bar strong {
+      font-size:13px;
+      letter-spacing:0.01em;
+    }
+    .mail-preview__bar span {
+      color:rgba(246,245,234,0.7);
+      font-family:var(--font-mono);
+      font-size:10px;
+    }
+    .mail-preview__chrome {
+      background:#fbfaf3;
+      border-bottom:1px solid var(--color-line);
+      display:grid;
+      gap:14px;
+      padding:18px 20px;
+    }
+    .mail-preview__subject {
+      align-items:flex-start;
+      display:flex;
+      gap:14px;
+      justify-content:space-between;
+    }
+    .mail-preview__subject h2 {
+      color:var(--color-ink);
+      font-size:23px;
+      font-weight:700;
+      letter-spacing:-0.026em;
+      line-height:1.16;
+    }
+    .mail-preview__subject p {
+      color:var(--color-ink-3);
+      font-size:12px;
+      margin-top:5px;
+    }
+    .metadata {
+      border:1px solid var(--color-line);
+      border-radius:16px;
+      display:grid;
+      overflow:hidden;
+    }
+    .metadata__row {
+      display:grid;
+      gap:12px;
+      grid-template-columns:92px 1fr;
+      padding:10px 12px;
+    }
+    .metadata__row + .metadata__row {
+      border-top:1px solid var(--color-line);
+    }
+    .metadata__label {
+      color:var(--color-ink-3);
+      font-size:11px;
+      font-weight:700;
+      letter-spacing:0.14em;
+      text-transform:uppercase;
+    }
+    .metadata__value {
+      color:var(--color-ink-2);
+      font-size:13px;
+      line-height:1.35;
+      min-width:0;
+      overflow-wrap:anywhere;
+    }
+    .metadata__value strong {
+      color:var(--color-ink);
+      font-weight:700;
+    }
+    .mail-preview__body {
+      background:#ece9e0;
+      padding:26px 16px 30px;
+    }
+    .email-shadow {
+      margin:0 auto;
+      max-width:560px;
+    }
+    .text-body {
+      background:var(--color-sage-800);
+      color:var(--color-cream);
+      display:grid;
+      gap:14px;
+      padding:18px 20px 22px;
+    }
+    .text-body__title {
+      align-items:center;
+      display:flex;
+      gap:10px;
+      justify-content:space-between;
+    }
+    .text-body__title h3 {
+      font-size:15px;
+      font-weight:700;
+      letter-spacing:-0.01em;
+    }
+    .text-body__title span {
+      color:rgba(246,245,234,0.68);
+      font-family:var(--font-mono);
+      font-size:10px;
+    }
+    .text-body pre {
+      background:rgba(246,245,234,0.08);
+      border:1px solid rgba(246,245,234,0.16);
+      border-radius:14px;
+      color:rgba(246,245,234,0.88);
+      font-size:12px;
+      line-height:1.55;
+      margin:0;
+      overflow:auto;
+      padding:14px;
+      white-space:pre-wrap;
+    }
+    .notes {
+      display:grid;
+      gap:12px;
+      grid-template-columns:repeat(3, minmax(0, 1fr));
+      margin:0 auto;
+      max-width:860px;
+      width:100%;
+    }
+    .note {
+      background:var(--color-paper);
+      border:1px solid var(--color-line-strong);
+      border-radius:18px;
+      padding:14px;
+    }
+    .note strong {
+      color:var(--color-ink);
+      display:block;
+      font-size:13px;
+      margin-bottom:4px;
+    }
+    .note span {
+      color:var(--color-ink-2);
+      display:block;
+      font-size:12px;
+      line-height:1.45;
+    }
+
+    @media (max-width:760px) {
+      .preview-shell { padding:18px; }
+      .preview-title {
+        align-items:flex-start;
+        flex-direction:column;
+      }
+      .mail-preview__subject {
+        display:grid;
+      }
+      .metadata__row {
+        grid-template-columns:1fr;
+        gap:4px;
+      }
+      .notes { grid-template-columns:1fr; }
+    }
+
+    @media only screen and (max-width:600px) {
+      .container { width:100% !important; max-width:100% !important; border-radius:0 !important; }
+      .gutter { padding-left:22px !important; padding-right:22px !important; }
+      .h1 { font-size:23px !important; }
+    }
+  </style>
+</head>
+<body>
+  <main class="preview-shell">
+    <header class="preview-title">
+      <div>
+        <p class="preview-title__eyebrow">Onboarding Requests</p>
+        <h1>New-request staff notification</h1>
+        <p>
+          Static preview of <code>Memba.Onboarding.NewRequestEmail</code>: a staff-only
+          notification from Memba with the requester as Reply-To and a direct conversion
+          link into <code>/admin/requests/:request_id</code>.
+        </p>
+      </div>
+      <span class="variant-label">repo: emails/new-request-notification.html</span>
+    </header>
+
+    <section class="mail-preview" aria-labelledby="email-subject">
+      <div class="mail-preview__bar">
+        <strong>Staff notification email</strong>
+        <span>Memba.Onboarding.NewRequestEmail</span>
+      </div>
+
+      <div class="mail-preview__chrome">
+        <div class="mail-preview__subject">
+          <div>
+            <h2 id="email-subject">New Memba request: West Coast Paddlers</h2>
+            <p>Preheader: New Memba access request for Memba staff.</p>
+          </div>
+          <span class="badge badge-info badge-soft">outbound-onboarding</span>
+        </div>
+
+        <div class="metadata" aria-label="Message envelope">
+          <div class="metadata__row">
+            <span class="metadata__label">From</span>
+            <span class="metadata__value"><strong>Memba</strong> &lt;hello@memba.io&gt;</span>
+          </div>
+          <div class="metadata__row">
+            <span class="metadata__label">To</span>
+            <span class="metadata__value">hello@memba.io</span>
+          </div>
+          <div class="metadata__row">
+            <span class="metadata__label">Reply-To</span>
+            <span class="metadata__value"><strong>Robin Requester</strong> &lt;robin@example.com&gt;</span>
+          </div>
+          <div class="metadata__row">
+            <span class="metadata__label">Open</span>
+            <span class="metadata__value">http://localhost:4000/admin/requests/req_9d7f82c9-74cb-45df-a610-2b164d8e9c5f</span>
+          </div>
+        </div>
+      </div>
+
+      <div class="mail-preview__body">
